import type {Lesson} from "./course-catalog";
// Conteúdo didático dos doze módulos adicionais de Química.
const lessons:Record<string,Lesson[]>={
"Introdução à Química":[
{"title":"Matéria e energia","explain":"Matéria possui massa e ocupa espaço; energia não é matéria, mas pode ser transferida.","example":"O ar dentro de um balão tem massa e volume.","question":"O ar é matéria?","options":["Sim, tem massa e volume","Não, é energia","Só quando está frio"],"correct":0,"feedback":"Resposta comentada: O ar dentro de um balão tem massa e volume. Matéria possui massa e ocupa espaço; energia não é matéria, mas pode ser transferida."},
{"title":"Propriedades gerais","explain":"Massa, volume e impenetrabilidade são propriedades gerais; densidade e pontos de fusão são propriedades específicas.","example":"Dois objetos podem ter o mesmo volume e massas diferentes.","question":"Qual propriedade ajuda a identificar uma substância?","options":["Volume apenas","Densidade","Quantidade de objetos"],"correct":1,"feedback":"Resposta comentada: Dois objetos podem ter o mesmo volume e massas diferentes. Massa, volume e impenetrabilidade são propriedades gerais; densidade e pontos de fusão são propriedades específicas."},
{"title":"Estados físicos","explain":"Sólidos têm forma e volume definidos; líquidos têm volume definido e forma variável; gases ocupam o recipiente.","example":"A água líquida assume a forma do copo.","question":"Qual estado tem volume definido e forma variável?","options":["Gasoso","Sólido","Líquido"],"correct":2,"feedback":"Resposta comentada: A água líquida assume a forma do copo. Sólidos têm forma e volume definidos; líquidos têm volume definido e forma variável; gases ocupam o recipiente."},
{"title":"Mudanças de estado","explain":"Fusão é sólido para líquido; vaporização é líquido para gás; condensação é gás para líquido; solidificação é líquido para sólido.","example":"Gelo derretendo passa por fusão.","question":"Gelo virando água sofre:","options":["Fusão","Condensação","Sublimação"],"correct":0,"feedback":"Resposta comentada: Gelo derretendo passa por fusão. Fusão é sólido para líquido; vaporização é líquido para gás; condensação é gás para líquido; solidificação é líquido para sólido."},
{"title":"Substâncias puras","explain":"Substância pura apresenta composição química definida; pode ser simples ou composta.","example":"Água destilada idealmente é constituída de H₂O.","question":"H₂O é substância:","options":["Simples","Composta","Mistura heterogênea"],"correct":1,"feedback":"Resposta comentada: Água destilada idealmente é constituída de H₂O. Substância pura apresenta composição química definida; pode ser simples ou composta."},
{"title":"Misturas homogêneas","explain":"Mistura homogênea apresenta uma fase observável e composição uniforme na escala considerada.","example":"Sal totalmente dissolvido em água forma uma solução.","question":"Água com sal dissolvido é:","options":["Substância simples","Mistura heterogênea","Mistura homogênea"],"correct":2,"feedback":"Resposta comentada: Sal totalmente dissolvido em água forma uma solução. Mistura homogênea apresenta uma fase observável e composição uniforme na escala considerada."},
{"title":"Misturas heterogêneas","explain":"Misturas heterogêneas apresentam duas ou mais fases discerníveis.","example":"Óleo e água separados formam duas fases.","question":"Óleo e água formam mistura:","options":["Heterogênea","Homogênea","Substância pura"],"correct":0,"feedback":"Resposta comentada: Óleo e água separados formam duas fases. Misturas heterogêneas apresentam duas ou mais fases discerníveis."},
{"title":"Filtração","explain":"Filtração separa sólido insolúvel de fluido por barreira porosa.","example":"Filtro de papel retém areia misturada à água.","question":"Qual método separa areia e água?","options":["Destilação fracionada","Filtração","Fusão"],"correct":1,"feedback":"Resposta comentada: Filtro de papel retém areia misturada à água. Filtração separa sólido insolúvel de fluido por barreira porosa."},
{"title":"Destilação simples","explain":"Destilação explora diferenças de volatilidade, vaporizando e condensando um componente.","example":"Água pode ser recuperada de solução salina por destilação.","question":"Qual processo recupera água do sal dissolvido?","options":["Peneiração","Decantação simples","Destilação"],"correct":2,"feedback":"Resposta comentada: Água pode ser recuperada de solução salina por destilação. Destilação explora diferenças de volatilidade, vaporizando e condensando um componente."},
{"title":"Separação por decantação","explain":"Decantação aproveita diferenças de densidade entre fases que se separam sob gravidade.","example":"Água e óleo podem ser separados em funil de separação.","question":"O método apropriado é:","options":["Decantação","Filtração de sal dissolvido","Sublimação"],"correct":0,"feedback":"Resposta comentada: Água e óleo podem ser separados em funil de separação. Decantação aproveita diferenças de densidade entre fases que se separam sob gravidade."},
],
"Modelos Atômicos":[
{"title":"Dalton","explain":"Dalton descreveu a matéria como formada por átomos indivisíveis em seu modelo histórico; hoje sabemos que possuem partículas subatômicas.","example":"A teoria de Dalton ajudou a explicar proporções fixas nas reações.","question":"No modelo de Dalton, o átomo era:","options":["Núcleo com elétrons","Esfera indivisível","Nuvem eletrônica"],"correct":1,"feedback":"Resposta comentada: A teoria de Dalton ajudou a explicar proporções fixas nas reações. Dalton descreveu a matéria como formada por átomos indivisíveis em seu modelo histórico; hoje sabemos que possuem partículas subatômicas."},
{"title":"Thomson","explain":"A descoberta do elétron levou Thomson a propor carga positiva difusa com elétrons incrustados.","example":"O modelo ficou conhecido como pudim de passas.","question":"Qual partícula Thomson identificou?","options":["Nêutron","Próton","Elétron"],"correct":2,"feedback":"Resposta comentada: O modelo ficou conhecido como pudim de passas. A descoberta do elétron levou Thomson a propor carga positiva difusa com elétrons incrustados."},
{"title":"Rutherford","explain":"O espalhamento de partículas alfa indicou um núcleo pequeno, denso e positivo, com grande parte do átomo sendo espaço vazio.","example":"Poucas partículas alfa sofreram grandes desvios na lâmina de ouro.","question":"O experimento revelou:","options":["Núcleo concentrado","Elétrons sem carga","Átomo maciço"],"correct":0,"feedback":"Resposta comentada: Poucas partículas alfa sofreram grandes desvios na lâmina de ouro. O espalhamento de partículas alfa indicou um núcleo pequeno, denso e positivo, com grande parte do átomo sendo espaço vazio."},
{"title":"Bohr","explain":"Bohr propôs níveis energéticos discretos para explicar linhas espectrais do hidrogênio.","example":"A transição para nível inferior emite fóton.","question":"Ao descer de nível, o elétron:","options":["Absorve energia sempre","Emite energia","Deixa de existir"],"correct":1,"feedback":"Resposta comentada: A transição para nível inferior emite fóton. Bohr propôs níveis energéticos discretos para explicar linhas espectrais do hidrogênio."},
{"title":"Prótons e nêutrons","explain":"Prótons possuem carga positiva e nêutrons são eletricamente neutros; ambos compõem o núcleo.","example":"Carbono-12 tem seis prótons e seis nêutrons.","question":"Qual partícula não possui carga?","options":["Elétron","Próton","Nêutron"],"correct":2,"feedback":"Resposta comentada: Carbono-12 tem seis prótons e seis nêutrons. Prótons possuem carga positiva e nêutrons são eletricamente neutros; ambos compõem o núcleo."},
{"title":"Número atômico","explain":"O número atômico Z é igual ao número de prótons do núcleo e identifica o elemento.","example":"Oxigênio tem Z=8, portanto oito prótons.","question":"Um átomo com Z=8 possui:","options":["8 prótons","8 nêutrons obrigatoriamente","16 prótons"],"correct":0,"feedback":"Resposta comentada: Oxigênio tem Z=8, portanto oito prótons. O número atômico Z é igual ao número de prótons do núcleo e identifica o elemento."},
{"title":"Número de massa","explain":"O número de massa A soma prótons e nêutrons: A=Z+N.","example":"Se Z=11 e N=12, A=23.","question":"Qual é o número de massa?","options":["12","23","11"],"correct":1,"feedback":"Resposta comentada: Se Z=11 e N=12, A=23. O número de massa A soma prótons e nêutrons: A=Z+N."},
{"title":"Íons","explain":"Cátions perdem elétrons e ficam positivos; ânions ganham elétrons e ficam negativos.","example":"Na⁺ forma-se quando sódio neutro perde um elétron.","question":"Na⁺ é um:","options":["Ânion","Isótopo obrigatoriamente","Cátion"],"correct":2,"feedback":"Resposta comentada: Na⁺ forma-se quando sódio neutro perde um elétron. Cátions perdem elétrons e ficam positivos; ânions ganham elétrons e ficam negativos."},
{"title":"Isótopos","explain":"Isótopos do mesmo elemento têm igual Z e diferentes números de nêutrons.","example":"Carbono-12 e carbono-14 possuem seis prótons.","question":"Isótopos têm igual número de:","options":["Prótons","Nêutrons","Massa"],"correct":0,"feedback":"Resposta comentada: Carbono-12 e carbono-14 possuem seis prótons. Isótopos do mesmo elemento têm igual Z e diferentes números de nêutrons."},
{"title":"Distribuição eletrônica","explain":"Elétrons ocupam orbitais e subníveis de energia seguindo regras quânticas de preenchimento.","example":"O átomo de sódio neutro tem 11 elétrons.","question":"Um átomo neutro de Z=11 possui:","options":["10 elétrons","11 elétrons","12 elétrons"],"correct":1,"feedback":"Resposta comentada: O átomo de sódio neutro tem 11 elétrons. Elétrons ocupam orbitais e subníveis de energia seguindo regras quânticas de preenchimento."},
],
"Funções Inorgânicas":[
{"title":"Ácidos de Arrhenius","explain":"Ácidos de Arrhenius aumentam a concentração de H₃O⁺ em solução aquosa.","example":"HCl em água produz íons hidrônio por transferência de prótons à água.","question":"Qual espécie aumenta em solução ácida?","options":["OH⁻ obrigatoriamente","Elétrons livres","H₃O⁺"],"correct":2,"feedback":"Resposta comentada: HCl em água produz íons hidrônio por transferência de prótons à água. Ácidos de Arrhenius aumentam a concentração de H₃O⁺ em solução aquosa."},
{"title":"Bases de Arrhenius","explain":"Bases de Arrhenius aumentam a concentração de OH⁻ em água.","example":"NaOH se dissocia formando Na⁺ e OH⁻.","question":"Qual íon caracteriza a base de Arrhenius?","options":["OH⁻","Cl⁻","Na⁺ apenas"],"correct":0,"feedback":"Resposta comentada: NaOH se dissocia formando Na⁺ e OH⁻. Bases de Arrhenius aumentam a concentração de OH⁻ em água."},
{"title":"Indicadores ácido-base","explain":"Indicadores mudam de cor conforme condições ácido-base, em faixas de pH características.","example":"Fenolftaleína tende a ficar rosa em soluções suficientemente básicas.","question":"Indicadores são usados para:","options":["Medir massa","Sinalizar faixa de pH","Criar elétrons"],"correct":1,"feedback":"Resposta comentada: Fenolftaleína tende a ficar rosa em soluções suficientemente básicas. Indicadores mudam de cor conforme condições ácido-base, em faixas de pH características."},
{"title":"Escala de pH","explain":"A 25 °C, em soluções aquosas ideais, pH=7 indica neutralidade, menor que 7 acidez e maior que 7 basicidade.","example":"Uma solução com pH=3 é ácida.","question":"pH=3 indica:","options":["Neutro","Básico","Ácido"],"correct":2,"feedback":"Resposta comentada: Uma solução com pH=3 é ácida. A 25 °C, em soluções aquosas ideais, pH=7 indica neutralidade, menor que 7 acidez e maior que 7 basicidade."},
{"title":"Neutralização","explain":"Ácido e base podem reagir produzindo sal e água em neutralizações típicas.","example":"HCl + NaOH → NaCl + H₂O.","question":"Quais produtos aparecem nesse exemplo?","options":["Sal e água","Oxigênio e metal","Apenas ácido"],"correct":0,"feedback":"Resposta comentada: HCl + NaOH → NaCl + H₂O. Ácido e base podem reagir produzindo sal e água em neutralizações típicas."},
{"title":"Sais","explain":"Sais são compostos iônicos frequentemente formados por cátions diferentes de H⁺ e ânions diferentes de OH⁻.","example":"NaCl é cloreto de sódio.","question":"NaCl é classificado como:","options":["Óxido","Sal","Ácido"],"correct":1,"feedback":"Resposta comentada: NaCl é cloreto de sódio. Sais são compostos iônicos frequentemente formados por cátions diferentes de H⁺ e ânions diferentes de OH⁻."},
{"title":"Óxidos","explain":"Óxidos são compostos binários em que oxigênio é ligado a outro elemento, com exceções específicas como compostos com flúor.","example":"CO₂ é dióxido de carbono.","question":"CO₂ é:","options":["Sal","Hidróxido","Óxido"],"correct":2,"feedback":"Resposta comentada: CO₂ é dióxido de carbono. Óxidos são compostos binários em que oxigênio é ligado a outro elemento, com exceções específicas como compostos com flúor."},
{"title":"Óxidos ácidos","explain":"Muitos óxidos de ametais reagem com água produzindo ácidos, embora nem todos reajam.","example":"SO₃ + H₂O → H₂SO₄.","question":"SO₃ é exemplo de óxido:","options":["Ácido","Básico metálico","Neutro obrigatoriamente"],"correct":0,"feedback":"Resposta comentada: SO₃ + H₂O → H₂SO₄. Muitos óxidos de ametais reagem com água produzindo ácidos, embora nem todos reajam."},
{"title":"Óxidos básicos","explain":"Óxidos de certos metais podem reagir com água formando hidróxidos.","example":"CaO + H₂O → Ca(OH)₂.","question":"CaO é um óxido:","options":["Ácido","Básico","Peróxido"],"correct":1,"feedback":"Resposta comentada: CaO + H₂O → Ca(OH)₂. Óxidos de certos metais podem reagir com água formando hidróxidos."},
{"title":"Nomenclatura inorgânica","explain":"A nomenclatura usa composição e estados de oxidação quando necessário para distinguir compostos.","example":"FeCl₃ é cloreto de ferro(III).","question":"Qual o NOX do ferro em FeCl₃?","options":["+2","+1","+3"],"correct":2,"feedback":"Resposta comentada: FeCl₃ é cloreto de ferro(III). A nomenclatura usa composição e estados de oxidação quando necessário para distinguir compostos."},
],
"Estequiometria":[
{"title":"Quantidade de matéria","explain":"O mol corresponde a 6,022×10²³ entidades elementares, aproximadamente, segundo a constante de Avogadro.","example":"Um mol de moléculas contém cerca de 6,022×10²³ moléculas.","question":"Um mol corresponde a:","options":["6,022×10²³ entidades","Uma única molécula","100 entidades"],"correct":0,"feedback":"Resposta comentada: Um mol de moléculas contém cerca de 6,022×10²³ moléculas. O mol corresponde a 6,022×10²³ entidades elementares, aproximadamente, segundo a constante de Avogadro."},
{"title":"Massa molar","explain":"Massa molar expressa a massa de um mol de partículas em g/mol.","example":"H₂O tem massa molar aproximada de 18 g/mol.","question":"Qual a massa de 2 mol de H₂O?","options":["18 g","36 g","9 g"],"correct":1,"feedback":"Resposta comentada: H₂O tem massa molar aproximada de 18 g/mol. Massa molar expressa a massa de um mol de partículas em g/mol."},
{"title":"Número de mols","explain":"A quantidade de matéria é n=m/M, onde m é massa e M massa molar.","example":"Para 44 g de CO₂, com M=44 g/mol, n=1 mol.","question":"44 g de CO₂ correspondem a:","options":["44 mol","0,5 mol","1 mol"],"correct":2,"feedback":"Resposta comentada: Para 44 g de CO₂, com M=44 g/mol, n=1 mol. A quantidade de matéria é n=m/M, onde m é massa e M massa molar."},
{"title":"Balanceamento","explain":"Equações químicas devem conservar a quantidade de átomos de cada elemento nos dois lados.","example":"2 H₂ + O₂ → 2 H₂O.","question":"Qual coeficiente de H₂ na reação balanceada?","options":["2","1","4"],"correct":0,"feedback":"Resposta comentada: 2 H₂ + O₂ → 2 H₂O. Equações químicas devem conservar a quantidade de átomos de cada elemento nos dois lados."},
{"title":"Proporções molares","explain":"Coeficientes estequiométricos representam proporções entre quantidades de matéria.","example":"Na reação 2 H₂ + O₂ → 2 H₂O, dois mols de H₂ produzem dois de água.","question":"2 mol de H₂ podem produzir:","options":["1 mol de H₂O","2 mol de H₂O","4 mol de H₂O"],"correct":1,"feedback":"Resposta comentada: Na reação 2 H₂ + O₂ → 2 H₂O, dois mols de H₂ produzem dois de água. Coeficientes estequiométricos representam proporções entre quantidades de matéria."},
{"title":"Reagente limitante","explain":"O reagente limitante é consumido primeiro e determina a quantidade máxima de produto.","example":"Com 2 mol H₂ e 2 mol O₂, H₂ limita a reação 2 H₂+O₂→2 H₂O.","question":"Qual é o limitante?","options":["O₂","H₂O","H₂"],"correct":2,"feedback":"Resposta comentada: Com 2 mol H₂ e 2 mol O₂, H₂ limita a reação 2 H₂+O₂→2 H₂O. O reagente limitante é consumido primeiro e determina a quantidade máxima de produto."},
{"title":"Rendimento teórico","explain":"O rendimento teórico é a quantidade máxima de produto prevista pela estequiometria, supondo conversão ideal.","example":"Se a conta prevê 10 g, esse é o rendimento teórico.","question":"O rendimento teórico é:","options":["Máximo calculado","Massa de impurezas","Massa de catalisador"],"correct":0,"feedback":"Resposta comentada: Se a conta prevê 10 g, esse é o rendimento teórico. O rendimento teórico é a quantidade máxima de produto prevista pela estequiometria, supondo conversão ideal."},
{"title":"Rendimento percentual","explain":"Rendimento percentual é massa real dividida pela teórica, vezes 100%.","example":"Se foram obtidos 8 g de 10 g previstos, o rendimento é 80%.","question":"Qual é o rendimento?","options":["125%","80%","20%"],"correct":1,"feedback":"Resposta comentada: Se foram obtidos 8 g de 10 g previstos, o rendimento é 80%. Rendimento percentual é massa real dividida pela teórica, vezes 100%."},
{"title":"Pureza de reagentes","explain":"A massa de reagente efetivamente disponível é a massa total multiplicada pela fração de pureza.","example":"100 g de amostra com 90% de pureza contêm 90 g da substância.","question":"Qual massa pura?","options":["10 g","100 g","90 g"],"correct":2,"feedback":"Resposta comentada: 100 g de amostra com 90% de pureza contêm 90 g da substância. A massa de reagente efetivamente disponível é a massa total multiplicada pela fração de pureza."},
{"title":"Volume molar de gases","explain":"Para gases ideais, volumes dependem de temperatura e pressão; nas mesmas condições, volumes são proporcionais aos mols.","example":"Em condições iguais, dois mols ocupam o dobro do volume de um mol.","question":"Ao dobrar n com T e p constantes, V:","options":["Dobra","Cai à metade","Não muda"],"correct":0,"feedback":"Resposta comentada: Em condições iguais, dois mols ocupam o dobro do volume de um mol. Para gases ideais, volumes dependem de temperatura e pressão; nas mesmas condições, volumes são proporcionais aos mols."},
],
"Soluções Químicas":[
{"title":"Soluto e solvente","explain":"Soluto é componente dissolvido; solvente é o meio que dissolve, normalmente em maior proporção.","example":"Em água salgada, o sal é soluto e a água é solvente.","question":"Qual é o solvente?","options":["Sal","Água","Cristal"],"correct":1,"feedback":"Resposta comentada: Em água salgada, o sal é soluto e a água é solvente. Soluto é componente dissolvido; solvente é o meio que dissolve, normalmente em maior proporção."},
{"title":"Concentração comum","explain":"Concentração comum C=m_soluto/V_solução, expressa frequentemente em g/L.","example":"10 g em 2 L resultam em 5 g/L.","question":"Qual concentração?","options":["20 g/L","0,2 g/L","5 g/L"],"correct":2,"feedback":"Resposta comentada: 10 g em 2 L resultam em 5 g/L. Concentração comum C=m_soluto/V_solução, expressa frequentemente em g/L."},
{"title":"Concentração molar","explain":"Molaridade é a quantidade de matéria do soluto por volume de solução em litros.","example":"0,5 mol em 1 L resulta em 0,5 mol/L.","question":"Qual molaridade?","options":["0,5 mol/L","2 mol/L","5 mol/L"],"correct":0,"feedback":"Resposta comentada: 0,5 mol em 1 L resulta em 0,5 mol/L. Molaridade é a quantidade de matéria do soluto por volume de solução em litros."},
{"title":"Diluição","explain":"Em diluição sem perda de soluto, C₁V₁=C₂V₂.","example":"100 mL de solução 2 mol/L diluídos para 200 mL produzem 1 mol/L.","question":"Qual concentração final?","options":["4 mol/L","1 mol/L","2 mol/L"],"correct":1,"feedback":"Resposta comentada: 100 mL de solução 2 mol/L diluídos para 200 mL produzem 1 mol/L. Em diluição sem perda de soluto, C₁V₁=C₂V₂."},
{"title":"Mistura de soluções","explain":"Ao misturar soluções do mesmo soluto sem reação, some quantidades de soluto e divida pelo volume final.","example":"1 L a 2 g/L mais 1 L a 4 g/L resulta em 3 g/L se volumes aditivos.","question":"Qual concentração final?","options":["6 g/L","2 g/L","3 g/L"],"correct":2,"feedback":"Resposta comentada: 1 L a 2 g/L mais 1 L a 4 g/L resulta em 3 g/L se volumes aditivos. Ao misturar soluções do mesmo soluto sem reação, some quantidades de soluto e divida pelo volume final."},
{"title":"Solubilidade","explain":"Solubilidade é a quantidade máxima de soluto dissolvível sob condições definidas.","example":"Se a solubilidade é 30 g por 100 g de água, 20 g dissolvem completamente nessa proporção.","question":"20 g nessas condições formam solução:","options":["Insaturada","Supersaturada obrigatoriamente","Saturada com corpo de fundo"],"correct":0,"feedback":"Resposta comentada: Se a solubilidade é 30 g por 100 g de água, 20 g dissolvem completamente nessa proporção. Solubilidade é a quantidade máxima de soluto dissolvível sob condições definidas."},
{"title":"Solução saturada","explain":"Solução saturada contém a quantidade máxima de soluto dissolvido em equilíbrio nas condições especificadas.","example":"Adicionar mais sólido a uma solução saturada pode deixar excesso não dissolvido.","question":"Solução saturada contém:","options":["Nenhum soluto","Máximo dissolvido em equilíbrio","Somente solvente"],"correct":1,"feedback":"Resposta comentada: Adicionar mais sólido a uma solução saturada pode deixar excesso não dissolvido. Solução saturada contém a quantidade máxima de soluto dissolvido em equilíbrio nas condições especificadas."},
{"title":"Curva de solubilidade","explain":"Curvas mostram como a solubilidade varia com temperatura; a tendência depende do soluto.","example":"Muitos sólidos ficam mais solúveis com aquecimento, mas existem exceções.","question":"A solubilidade sempre aumenta ao aquecer?","options":["Sim, para todos","Só em gases","Não, depende do sistema"],"correct":2,"feedback":"Resposta comentada: Muitos sólidos ficam mais solúveis com aquecimento, mas existem exceções. Curvas mostram como a solubilidade varia com temperatura; a tendência depende do soluto."},
{"title":"Fração em massa","explain":"Fração em massa é massa do componente dividida pela massa total da solução.","example":"10 g de soluto em 100 g de solução correspondem a 10% m/m.","question":"Qual porcentagem?","options":["10%","1%","100%"],"correct":0,"feedback":"Resposta comentada: 10 g de soluto em 100 g de solução correspondem a 10% m/m. Fração em massa é massa do componente dividida pela massa total da solução."},
{"title":"Partes por milhão","explain":"ppm em massa equivale a uma parte de soluto por um milhão de partes de solução.","example":"1 mg/kg corresponde a 1 ppm em massa.","question":"1 mg/kg equivale a:","options":["100 ppm","1 ppm","1000 ppm"],"correct":1,"feedback":"Resposta comentada: 1 mg/kg corresponde a 1 ppm em massa. ppm em massa equivale a uma parte de soluto por um milhão de partes de solução."},
],
"Termoquímica":[
{"title":"Sistema e vizinhança","explain":"Sistema é a porção analisada; vizinhança é o restante que troca energia com ele.","example":"Uma reação em béquer pode transferir calor ao ambiente.","question":"O sistema pode:","options":["Ser apenas o planeta","Não trocar energia","Trocar energia com a vizinhança"],"correct":2,"feedback":"Resposta comentada: Uma reação em béquer pode transferir calor ao ambiente. Sistema é a porção analisada; vizinhança é o restante que troca energia com ele."},
{"title":"Reação exotérmica","explain":"Reações exotérmicas liberam calor para a vizinhança; sob pressão constante, ΔH é negativo.","example":"Combustão de metano é exotérmica.","question":"Qual sinal de ΔH?","options":["Negativo","Positivo sempre","Zero sempre"],"correct":0,"feedback":"Resposta comentada: Combustão de metano é exotérmica. Reações exotérmicas liberam calor para a vizinhança; sob pressão constante, ΔH é negativo."},
{"title":"Reação endotérmica","explain":"Reações endotérmicas absorvem calor da vizinhança; sob pressão constante, ΔH é positivo.","example":"Decomposição térmica de CaCO₃ requer fornecimento de energia.","question":"Qual sinal de ΔH?","options":["Negativo","Positivo","Sempre nulo"],"correct":1,"feedback":"Resposta comentada: Decomposição térmica de CaCO₃ requer fornecimento de energia. Reações endotérmicas absorvem calor da vizinhança; sob pressão constante, ΔH é positivo."},
{"title":"Entalpia","explain":"Entalpia é função de estado; sob pressão constante e apenas trabalho pV, ΔH corresponde ao calor trocado.","example":"Uma reação com ΔH=−100 kJ libera 100 kJ por avanço estequiométrico definido.","question":"ΔH=−100 kJ indica:","options":["Absorção de 100 kJ","Sem calor","Liberação de 100 kJ"],"correct":2,"feedback":"Resposta comentada: Uma reação com ΔH=−100 kJ libera 100 kJ por avanço estequiométrico definido. Entalpia é função de estado; sob pressão constante e apenas trabalho pV, ΔH corresponde ao calor trocado."},
{"title":"Equações termoquímicas","explain":"Ao multiplicar coeficientes de uma reação por fator, o ΔH correspondente também é multiplicado.","example":"Dobrar uma reação com ΔH=−50 kJ resulta em −100 kJ.","question":"Qual novo ΔH?","options":["−100 kJ","−25 kJ","+50 kJ"],"correct":0,"feedback":"Resposta comentada: Dobrar uma reação com ΔH=−50 kJ resulta em −100 kJ. Ao multiplicar coeficientes de uma reação por fator, o ΔH correspondente também é multiplicado."},
{"title":"Lei de Hess","explain":"A variação de entalpia global é a soma das variações das etapas, pois entalpia é função de estado.","example":"Duas etapas com ΔH=−30 e +10 kJ totalizam −20 kJ.","question":"Qual ΔH global?","options":["+20 kJ","−20 kJ","−40 kJ"],"correct":1,"feedback":"Resposta comentada: Duas etapas com ΔH=−30 e +10 kJ totalizam −20 kJ. A variação de entalpia global é a soma das variações das etapas, pois entalpia é função de estado."},
{"title":"Entalpia de formação","explain":"Entalpia padrão de formação refere-se à formação de um mol de composto a partir de elementos em estados padrão.","example":"A entalpia padrão de formação de elemento em seu estado padrão é zero por convenção.","question":"Qual é esse valor?","options":["1 kJ/mol","−1 kJ/mol","0 kJ/mol"],"correct":2,"feedback":"Resposta comentada: A entalpia padrão de formação de elemento em seu estado padrão é zero por convenção. Entalpia padrão de formação refere-se à formação de um mol de composto a partir de elementos em estados padrão."},
{"title":"Energia de ligação","explain":"Aproximação: ΔH≈energia das ligações rompidas menos energia das ligações formadas.","example":"Romper ligações absorve energia; formar ligações libera energia.","question":"Romper ligações:","options":["Requer energia","Libera energia sempre","Não envolve energia"],"correct":0,"feedback":"Resposta comentada: Romper ligações absorve energia; formar ligações libera energia. Aproximação: ΔH≈energia das ligações rompidas menos energia das ligações formadas."},
{"title":"Calorimetria","explain":"Em sistema idealmente isolado, o calor perdido por um corpo iguala o recebido por outro.","example":"Água quente e fria misturadas tendem a atingir temperatura intermediária.","question":"O calor líquido trocado com exterior ideal é:","options":["Positivo sempre","Zero","Infinito"],"correct":1,"feedback":"Resposta comentada: Água quente e fria misturadas tendem a atingir temperatura intermediária. Em sistema idealmente isolado, o calor perdido por um corpo iguala o recebido por outro."},
{"title":"Combustíveis","explain":"Poder calorífico indica energia liberada por quantidade de combustível em combustão completa sob condições especificadas.","example":"Combustíveis diferentes possuem valores energéticos distintos.","question":"Poder calorífico mede:","options":["Volume de oxigênio","Massa atômica","Energia por quantidade de combustível"],"correct":2,"feedback":"Resposta comentada: Combustíveis diferentes possuem valores energéticos distintos. Poder calorífico indica energia liberada por quantidade de combustível em combustão completa sob condições especificadas."},
],
"Cinética Química":[
{"title":"Velocidade de reação","explain":"Velocidade média mede variação de concentração por intervalo de tempo, com sinal ajustado para reagentes e produtos.","example":"Se produto cresce 0,2 mol/L em 10 s, taxa média é 0,02 mol/(L·s).","question":"Qual é a taxa?","options":["0,02 mol/(L·s)","2 mol/(L·s)","20 mol/(L·s)"],"correct":0,"feedback":"Resposta comentada: Se produto cresce 0,2 mol/L em 10 s, taxa média é 0,02 mol/(L·s). Velocidade média mede variação de concentração por intervalo de tempo, com sinal ajustado para reagentes e produtos."},
{"title":"Teoria das colisões","explain":"Para reação ocorrer, partículas devem colidir com orientação e energia adequadas.","example":"Nem toda colisão molecular resulta em produto.","question":"Colisões eficazes exigem:","options":["Apenas alta massa","Energia e orientação adequadas","Ausência de contato"],"correct":1,"feedback":"Resposta comentada: Nem toda colisão molecular resulta em produto. Para reação ocorrer, partículas devem colidir com orientação e energia adequadas."},
{"title":"Energia de ativação","explain":"Energia de ativação é barreira energética associada ao caminho reacional.","example":"Uma barreira maior geralmente reduz a velocidade a temperatura fixa.","question":"Barreira maior tende a:","options":["Acelerar sempre","Não afetar","Reduzir a velocidade"],"correct":2,"feedback":"Resposta comentada: Uma barreira maior geralmente reduz a velocidade a temperatura fixa. Energia de ativação é barreira energética associada ao caminho reacional."},
{"title":"Temperatura","explain":"Aumento de temperatura geralmente eleva a constante de velocidade e a fração de colisões eficazes.","example":"Alimentos podem deteriorar mais rapidamente fora da geladeira.","question":"Aquecer geralmente:","options":["Aumenta a velocidade","Interrompe toda reação","Elimina colisões"],"correct":0,"feedback":"Resposta comentada: Alimentos podem deteriorar mais rapidamente fora da geladeira. Aumento de temperatura geralmente eleva a constante de velocidade e a fração de colisões eficazes."},
{"title":"Concentração","explain":"Para muitas reações, aumentar a concentração dos reagentes aumenta a frequência de encontros e a velocidade.","example":"Uma reação pode ser mais rápida com solução mais concentrada.","question":"Concentração maior geralmente:","options":["Diminui encontros","Aumenta encontros","Elimina reagentes"],"correct":1,"feedback":"Resposta comentada: Uma reação pode ser mais rápida com solução mais concentrada. Para muitas reações, aumentar a concentração dos reagentes aumenta a frequência de encontros e a velocidade."},
{"title":"Superfície de contato","explain":"Sólidos pulverizados oferecem maior área de contato que blocos da mesma massa.","example":"Palha de aço pode oxidar mais rapidamente que um bloco compacto.","question":"Qual forma tende a reagir mais rápido?","options":["Bloco grande","Ambas sempre iguais","Pó fino"],"correct":2,"feedback":"Resposta comentada: Palha de aço pode oxidar mais rapidamente que um bloco compacto. Sólidos pulverizados oferecem maior área de contato que blocos da mesma massa."},
{"title":"Catalisadores","explain":"Catalisadores alteram o mecanismo e reduzem a energia de ativação efetiva, sem alterar o equilíbrio termodinâmico.","example":"Enzimas catalisam reações biológicas.","question":"Catalisador geralmente:","options":["Reduz a barreira de ativação","É sempre consumido totalmente","Altera ΔH global"],"correct":0,"feedback":"Resposta comentada: Enzimas catalisam reações biológicas. Catalisadores alteram o mecanismo e reduzem a energia de ativação efetiva, sem alterar o equilíbrio termodinâmico."},
{"title":"Lei de velocidade","explain":"Uma lei experimental pode ter forma v=k[A]^m[B]^n; expoentes são determinados por experimentos.","example":"Se v=k[A]², dobrar [A] quadruplica a velocidade.","question":"Ao dobrar [A], v fica:","options":["Duas vezes","Quatro vezes","Oito vezes"],"correct":1,"feedback":"Resposta comentada: Se v=k[A]², dobrar [A] quadruplica a velocidade. Uma lei experimental pode ter forma v=k[A]^m[B]^n; expoentes são determinados por experimentos."},
{"title":"Ordem de reação","explain":"A ordem global é a soma dos expoentes das concentrações na lei de velocidade experimental.","example":"Para v=k[A][B]², a ordem global é três.","question":"Qual é a ordem?","options":["1","2","3"],"correct":2,"feedback":"Resposta comentada: Para v=k[A][B]², a ordem global é três. A ordem global é a soma dos expoentes das concentrações na lei de velocidade experimental."},
{"title":"Perfil energético","explain":"Diagramas energéticos mostram reagentes, produtos e barreira de ativação; catalisador reduz a barreira, não ΔH.","example":"Duas rotas podem ter o mesmo ΔH e diferentes energias de ativação.","question":"Catalisador altera principalmente:","options":["Energia de ativação","Entalpia dos produtos","Composição elementar"],"correct":0,"feedback":"Resposta comentada: Duas rotas podem ter o mesmo ΔH e diferentes energias de ativação. Diagramas energéticos mostram reagentes, produtos e barreira de ativação; catalisador reduz a barreira, não ΔH."},
],
"Equilíbrio Químico":[
{"title":"Equilíbrio dinâmico","explain":"No equilíbrio químico, as velocidades direta e inversa são iguais, embora ambas continuem ocorrendo.","example":"Em sistema fechado, concentrações podem ficar constantes sem cessar reações.","question":"No equilíbrio, velocidades são:","options":["Nulas obrigatoriamente","Iguais","Sempre diferentes"],"correct":1,"feedback":"Resposta comentada: Em sistema fechado, concentrações podem ficar constantes sem cessar reações. No equilíbrio químico, as velocidades direta e inversa são iguais, embora ambas continuem ocorrendo."},
{"title":"Constante Kc","explain":"Kc relaciona concentrações de produtos e reagentes elevadas aos coeficientes, omitindo sólidos e líquidos puros.","example":"Para A⇌B, Kc=[B]/[A].","question":"Para A⇌B, Kc é:","options":["[A]+[B]","[A]/[B]","[B]/[A]"],"correct":2,"feedback":"Resposta comentada: Para A⇌B, Kc=[B]/[A]. Kc relaciona concentrações de produtos e reagentes elevadas aos coeficientes, omitindo sólidos e líquidos puros."},
{"title":"Quociente Q","explain":"Q tem forma semelhante a K, mas usa concentrações instantâneas; Q<K favorece avanço direto para atingir equilíbrio.","example":"Se Q<K, há tendência líquida de formação de produtos.","question":"Q<K favorece:","options":["Reação direta","Reação inversa","Parada total"],"correct":0,"feedback":"Resposta comentada: Se Q<K, há tendência líquida de formação de produtos. Q tem forma semelhante a K, mas usa concentrações instantâneas; Q<K favorece avanço direto para atingir equilíbrio."},
{"title":"Le Chatelier","explain":"Perturbações de um sistema em equilíbrio podem induzir resposta que atenua o efeito imposto.","example":"Adicionar reagente costuma favorecer consumo parcial desse reagente.","question":"Adicionar reagente tende a favorecer:","options":["A reação inversa sempre","A reação direta","Nenhuma resposta possível"],"correct":1,"feedback":"Resposta comentada: Adicionar reagente costuma favorecer consumo parcial desse reagente. Perturbações de um sistema em equilíbrio podem induzir resposta que atenua o efeito imposto."},
{"title":"Pressão e gases","explain":"Ao comprimir sistema gasoso em equilíbrio, pode ser favorecido o lado com menor número de mols gasosos, quando há diferença.","example":"N₂+3H₂⇌2NH₃: compressão favorece NH₃ em condições adequadas.","question":"Qual lado tem menos mols gasosos?","options":["Reagentes","Iguais","Produtos"],"correct":2,"feedback":"Resposta comentada: N₂+3H₂⇌2NH₃: compressão favorece NH₃ em condições adequadas. Ao comprimir sistema gasoso em equilíbrio, pode ser favorecido o lado com menor número de mols gasosos, quando há diferença."},
{"title":"Temperatura no equilíbrio","explain":"A constante de equilíbrio depende da temperatura; aquecer favorece o sentido endotérmico.","example":"Em reação direta exotérmica, elevar temperatura favorece a inversa.","question":"Ao aquecer, favorece-se o sentido:","options":["Endotérmico","Exotérmico sempre","Sem variação"],"correct":0,"feedback":"Resposta comentada: Em reação direta exotérmica, elevar temperatura favorece a inversa. A constante de equilíbrio depende da temperatura; aquecer favorece o sentido endotérmico."},
{"title":"pH e pOH","explain":"Em água a 25 °C, pH+pOH=14 em condições usuais de soluções diluídas.","example":"Se pH=5, pOH=9.","question":"Qual é o pOH?","options":["5","9","14"],"correct":1,"feedback":"Resposta comentada: Se pH=5, pOH=9. Em água a 25 °C, pH+pOH=14 em condições usuais de soluções diluídas."},
{"title":"Ácidos fortes e fracos","explain":"Força de ácido refere-se ao grau de ionização em água, não à concentração inicial.","example":"Ácido fraco pode estar concentrado; ácido forte pode estar diluído.","question":"Força ácida mede:","options":["Quantidade de solução","Cor da solução","Tendência à ionização"],"correct":2,"feedback":"Resposta comentada: Ácido fraco pode estar concentrado; ácido forte pode estar diluído. Força de ácido refere-se ao grau de ionização em água, não à concentração inicial."},
{"title":"Produto de solubilidade","explain":"Kps descreve equilíbrio de dissolução de sal pouco solúvel; valores e estequiometria permitem avaliar precipitação.","example":"Para AgCl(s)⇌Ag⁺+Cl⁻, Kps=[Ag⁺][Cl⁻].","question":"A expressão de Kps é:","options":["[Ag⁺][Cl⁻]","[AgCl(s)]","[Ag⁺]+[Cl⁻]"],"correct":0,"feedback":"Resposta comentada: Para AgCl(s)⇌Ag⁺+Cl⁻, Kps=[Ag⁺][Cl⁻]. Kps descreve equilíbrio de dissolução de sal pouco solúvel; valores e estequiometria permitem avaliar precipitação."},
{"title":"Soluções tampão","explain":"Tampões contêm pares ácido-base conjugados capazes de atenuar variações de pH após pequenas adições de ácido ou base.","example":"Ácido acético e acetato podem formar sistema tampão.","question":"Tampão serve para:","options":["Impedir qualquer reação","Resistir a pequenas variações de pH","Fixar sempre pH=7"],"correct":1,"feedback":"Resposta comentada: Ácido acético e acetato podem formar sistema tampão. Tampões contêm pares ácido-base conjugados capazes de atenuar variações de pH após pequenas adições de ácido ou base."},
],
"Eletroquímica":[
{"title":"Oxidação e redução","explain":"Oxidação é perda de elétrons; redução é ganho de elétrons.","example":"Zn→Zn²⁺+2e⁻ representa oxidação.","question":"Perder elétrons é:","options":["Redução","Neutralização","Oxidação"],"correct":2,"feedback":"Resposta comentada: Zn→Zn²⁺+2e⁻ representa oxidação. Oxidação é perda de elétrons; redução é ganho de elétrons."},
{"title":"Agente oxidante","explain":"Agente oxidante recebe elétrons e sofre redução; agente redutor doa elétrons e sofre oxidação.","example":"Cu²⁺ recebe elétrons e vira Cu metálico.","question":"Quem recebe elétrons é:","options":["Agente oxidante","Agente redutor sempre","Eletrólito neutro"],"correct":0,"feedback":"Resposta comentada: Cu²⁺ recebe elétrons e vira Cu metálico. Agente oxidante recebe elétrons e sofre redução; agente redutor doa elétrons e sofre oxidação."},
{"title":"Número de oxidação","explain":"NOX é ferramenta contábil para rastrear transferência eletrônica em reações.","example":"Em NaCl, Na tem NOX +1 e Cl −1.","question":"Qual NOX do sódio em NaCl?","options":["−1","+1","0"],"correct":1,"feedback":"Resposta comentada: Em NaCl, Na tem NOX +1 e Cl −1. NOX é ferramenta contábil para rastrear transferência eletrônica em reações."},
{"title":"Pilhas galvânicas","explain":"Pilhas convertem energia química de reação redox espontânea em energia elétrica.","example":"Uma pilha Daniell usa eletrodos de zinco e cobre.","question":"Uma pilha galvânica produz:","options":["Somente calor","Luz obrigatoriamente","Energia elétrica"],"correct":2,"feedback":"Resposta comentada: Uma pilha Daniell usa eletrodos de zinco e cobre. Pilhas convertem energia química de reação redox espontânea em energia elétrica."},
{"title":"Ânodo e cátodo","explain":"Oxidação ocorre no ânodo e redução no cátodo, tanto em pilhas quanto em eletrólise.","example":"Na pilha Daniell, zinco oxida no ânodo.","question":"No ânodo ocorre:","options":["Oxidação","Redução","Condensação"],"correct":0,"feedback":"Resposta comentada: Na pilha Daniell, zinco oxida no ânodo. Oxidação ocorre no ânodo e redução no cátodo, tanto em pilhas quanto em eletrólise."},
{"title":"Ponte salina","explain":"A ponte salina permite migração iônica para manter eletroneutralidade nas semicélulas.","example":"Sem fluxo iônico adequado, o circuito de uma pilha deixa de operar continuamente.","question":"Ponte salina transporta principalmente:","options":["Elétrons pelo sal","Íons","Prótons apenas"],"correct":1,"feedback":"Resposta comentada: Sem fluxo iônico adequado, o circuito de uma pilha deixa de operar continuamente. A ponte salina permite migração iônica para manter eletroneutralidade nas semicélulas."},
{"title":"Potencial da célula","explain":"O potencial padrão da pilha é E°cel=E°cátodo−E°ânodo, usando potenciais padrão de redução.","example":"Se E°cátodo=+0,34 V e E°ânodo=−0,76 V, E°cel=1,10 V.","question":"Qual E°cel?","options":["−1,10 V","0,42 V","+1,10 V"],"correct":2,"feedback":"Resposta comentada: Se E°cátodo=+0,34 V e E°ânodo=−0,76 V, E°cel=1,10 V. O potencial padrão da pilha é E°cel=E°cátodo−E°ânodo, usando potenciais padrão de redução."},
{"title":"Eletrólise","explain":"Eletrólise usa energia elétrica externa para forçar uma reação redox não espontânea.","example":"Eletrólise da água pode produzir hidrogênio e oxigênio.","question":"Eletrólise requer:","options":["Fonte elétrica externa","Apenas gravidade","Nenhuma energia"],"correct":0,"feedback":"Resposta comentada: Eletrólise da água pode produzir hidrogênio e oxigênio. Eletrólise usa energia elétrica externa para forçar uma reação redox não espontânea."},
{"title":"Lei de Faraday","explain":"Carga elétrica é Q=It e quantidade de elétrons transferidos é Q/F, com F≈96485 C/mol.","example":"Corrente de 2 A por 10 s transfere 20 C.","question":"Qual carga?","options":["5 C","20 C","200 C"],"correct":1,"feedback":"Resposta comentada: Corrente de 2 A por 10 s transfere 20 C. Carga elétrica é Q=It e quantidade de elétrons transferidos é Q/F, com F≈96485 C/mol."},
{"title":"Corrosão","explain":"Corrosão metálica envolve reações eletroquímicas com o meio; revestimentos e proteção catódica podem reduzi-la.","example":"Ferro pode oxidar na presença de água e oxigênio.","question":"Qual medida ajuda a proteger o ferro?","options":["Remover toda proteção","Aumentar umidade","Aplicar revestimento protetor"],"correct":2,"feedback":"Resposta comentada: Ferro pode oxidar na presença de água e oxigênio. Corrosão metálica envolve reações eletroquímicas com o meio; revestimentos e proteção catódica podem reduzi-la."},
],
"Química Orgânica":[
{"title":"Carbono e tetravalência","explain":"Carbono frequentemente forma quatro ligações covalentes e cadeias de diferentes geometrias.","example":"Metano CH₄ possui quatro ligações C–H.","question":"Quantas ligações o carbono faz no CH₄?","options":["4","2","1"],"correct":0,"feedback":"Resposta comentada: Metano CH₄ possui quatro ligações C–H. Carbono frequentemente forma quatro ligações covalentes e cadeias de diferentes geometrias."},
{"title":"Cadeias carbônicas","explain":"Cadeias podem ser abertas, fechadas, saturadas, insaturadas, ramificadas ou não.","example":"Butano apresenta cadeia aberta e saturada.","question":"Cadeia só com ligações simples C–C é:","options":["Insaturada","Saturada","Aromática obrigatoriamente"],"correct":1,"feedback":"Resposta comentada: Butano apresenta cadeia aberta e saturada. Cadeias podem ser abertas, fechadas, saturadas, insaturadas, ramificadas ou não."},
{"title":"Alcanos","explain":"Alcanos acíclicos saturados têm fórmula geral CₙH₂ₙ₊₂.","example":"Propano é C₃H₈.","question":"Qual fórmula do propano?","options":["C₃H₆","C₃H₄","C₃H₈"],"correct":2,"feedback":"Resposta comentada: Propano é C₃H₈. Alcanos acíclicos saturados têm fórmula geral CₙH₂ₙ₊₂."},
{"title":"Alcenos e alcinos","explain":"Alcenos possuem dupla ligação C=C; alcinos possuem tripla ligação C≡C.","example":"Eteno C₂H₄ possui uma dupla ligação.","question":"Eteno é:","options":["Alceno","Alcano","Álcool"],"correct":0,"feedback":"Resposta comentada: Eteno C₂H₄ possui uma dupla ligação. Alcenos possuem dupla ligação C=C; alcinos possuem tripla ligação C≡C."},
{"title":"Aromáticos","explain":"Compostos aromáticos possuem sistemas cíclicos conjugados com estabilização eletrônica característica.","example":"Benzeno C₆H₆ é exemplo clássico.","question":"Benzeno é:","options":["Álcool","Aromático","Sal"],"correct":1,"feedback":"Resposta comentada: Benzeno C₆H₆ é exemplo clássico. Compostos aromáticos possuem sistemas cíclicos conjugados com estabilização eletrônica característica."},
{"title":"Álcoois","explain":"Álcoois possuem grupo hidroxila ligado a carbono saturado; fenóis têm OH diretamente ligado ao anel aromático.","example":"Etanol CH₃CH₂OH é um álcool.","question":"Qual grupo funcional do etanol?","options":["Carboxila","Amina","Hidroxila"],"correct":2,"feedback":"Resposta comentada: Etanol CH₃CH₂OH é um álcool. Álcoois possuem grupo hidroxila ligado a carbono saturado; fenóis têm OH diretamente ligado ao anel aromático."},
{"title":"Aldeídos e cetonas","explain":"Aldeídos possuem carbonila terminal ligada a H; cetonas têm carbonila entre carbonos.","example":"Propanona (acetona) é uma cetona.","question":"A acetona é:","options":["Cetona","Aldeído","Éster"],"correct":0,"feedback":"Resposta comentada: Propanona (acetona) é uma cetona. Aldeídos possuem carbonila terminal ligada a H; cetonas têm carbonila entre carbonos."},
{"title":"Ácidos carboxílicos","explain":"Ácidos carboxílicos contêm grupo –COOH, que pode doar próton em água.","example":"Ácido acético está presente no vinagre.","question":"Qual grupo caracteriza esses ácidos?","options":["–OH isolado","–COOH","–NH₂ apenas"],"correct":1,"feedback":"Resposta comentada: Ácido acético está presente no vinagre. Ácidos carboxílicos contêm grupo –COOH, que pode doar próton em água."},
{"title":"Ésteres","explain":"Ésteres apresentam grupo –COO– entre fragmentos orgânicos e podem ser obtidos por esterificação.","example":"Acetato de etila é um éster comum.","question":"Qual grupo caracteriza ésteres?","options":["–NH₂","–CHO","–COO–"],"correct":2,"feedback":"Resposta comentada: Acetato de etila é um éster comum. Ésteres apresentam grupo –COO– entre fragmentos orgânicos e podem ser obtidos por esterificação."},
{"title":"Isomeria","explain":"Isômeros possuem mesma fórmula molecular, mas estruturas ou disposições espaciais distintas.","example":"Etanol e éter dimetílico possuem fórmula C₂H₆O.","question":"Isômeros possuem mesma:","options":["Fórmula molecular","Estrutura obrigatoriamente","Função química sempre"],"correct":0,"feedback":"Resposta comentada: Etanol e éter dimetílico possuem fórmula C₂H₆O. Isômeros possuem mesma fórmula molecular, mas estruturas ou disposições espaciais distintas."},
],
"Polímeros e Materiais":[
{"title":"Monômeros e polímeros","explain":"Polímeros são macromoléculas formadas por unidades repetitivas; monômeros são moléculas precursoras.","example":"Eteno pode originar polietileno por polimerização.","question":"Unidade precursora chama-se:","options":["Catalisador","Monômero","Íon metálico"],"correct":1,"feedback":"Resposta comentada: Eteno pode originar polietileno por polimerização. Polímeros são macromoléculas formadas por unidades repetitivas; monômeros são moléculas precursoras."},
{"title":"Polimerização por adição","explain":"Monômeros insaturados podem se unir em cadeia sem eliminação de pequenas moléculas.","example":"Eteno forma polietileno por adição.","question":"Polietileno pode ser obtido por:","options":["Neutralização","Destilação","Adição"],"correct":2,"feedback":"Resposta comentada: Eteno forma polietileno por adição. Monômeros insaturados podem se unir em cadeia sem eliminação de pequenas moléculas."},
{"title":"Polimerização por condensação","explain":"Certas polimerizações formam ligações entre monômeros com eliminação de moléculas pequenas, como água.","example":"Alguns poliésteres são produzidos por condensação.","question":"Qual subproduto pode surgir?","options":["Água","Oxigênio atômico sempre","Elétron livre"],"correct":0,"feedback":"Resposta comentada: Alguns poliésteres são produzidos por condensação. Certas polimerizações formam ligações entre monômeros com eliminação de moléculas pequenas, como água."},
{"title":"Polietileno","explain":"Polietileno é polímero amplamente usado em embalagens e recipientes, com propriedades dependentes da estrutura.","example":"Sacolas e frascos podem ser feitos de diferentes graus de PE.","question":"PE significa:","options":["Poliéster","Polietileno","Poliamida"],"correct":1,"feedback":"Resposta comentada: Sacolas e frascos podem ser feitos de diferentes graus de PE. Polietileno é polímero amplamente usado em embalagens e recipientes, com propriedades dependentes da estrutura."},
{"title":"PET","explain":"PET é poliéster utilizado em garrafas e fibras têxteis; reciclagem depende de coleta e processamento adequados.","example":"Garrafas de bebidas podem ser fabricadas com PET.","question":"PET é um:","options":["Metal","Sal","Poliéster"],"correct":2,"feedback":"Resposta comentada: Garrafas de bebidas podem ser fabricadas com PET. PET é poliéster utilizado em garrafas e fibras têxteis; reciclagem depende de coleta e processamento adequados."},
{"title":"Termoplásticos","explain":"Termoplásticos amolecem com aquecimento e podem ser remodelados em condições apropriadas.","example":"PE e PP são exemplos de termoplásticos.","question":"Qual comportamento é típico?","options":["Amolecem ao aquecer","Nunca deformam","Viraram metais"],"correct":0,"feedback":"Resposta comentada: PE e PP são exemplos de termoplásticos. Termoplásticos amolecem com aquecimento e podem ser remodelados em condições apropriadas."},
{"title":"Termofixos","explain":"Termofixos apresentam redes reticuladas e não fundem para remodelagem convencional após cura.","example":"Resinas epóxi curadas podem formar redes rígidas.","question":"Termofixos após cura:","options":["Fundem repetidamente como água","Não são facilmente remoldáveis por fusão","São sempre gases"],"correct":1,"feedback":"Resposta comentada: Resinas epóxi curadas podem formar redes rígidas. Termofixos apresentam redes reticuladas e não fundem para remodelagem convencional após cura."},
{"title":"Elastômeros","explain":"Elastômeros podem sofrer grandes deformações reversíveis devido à estrutura molecular.","example":"Borracha de pneus é exemplo de material elastomérico.","question":"Propriedade característica:","options":["Fragilidade obrigatória","Alta condutividade metálica","Elasticidade"],"correct":2,"feedback":"Resposta comentada: Borracha de pneus é exemplo de material elastomérico. Elastômeros podem sofrer grandes deformações reversíveis devido à estrutura molecular."},
{"title":"Biopolímeros","explain":"Polímeros naturais incluem celulose, proteínas e DNA; origem biológica não implica biodegradação rápida em qualquer ambiente.","example":"Celulose forma parte estrutural das plantas.","question":"Celulose é um:","options":["Polímero natural","Metal","Óxido"],"correct":0,"feedback":"Resposta comentada: Celulose forma parte estrutural das plantas. Polímeros naturais incluem celulose, proteínas e DNA; origem biológica não implica biodegradação rápida em qualquer ambiente."},
{"title":"Reciclagem de polímeros","explain":"Reciclagem mecânica envolve coleta, separação, moagem e reprocessamento; contaminação e mistura de materiais dificultam o processo.","example":"Separar PET de outros plásticos melhora a qualidade do material reciclado.","question":"Qual prática ajuda a reciclar?","options":["Misturar todos sem triagem","Separar materiais","Descartar em rios"],"correct":1,"feedback":"Resposta comentada: Separar PET de outros plásticos melhora a qualidade do material reciclado. Reciclagem mecânica envolve coleta, separação, moagem e reprocessamento; contaminação e mistura de materiais dificultam o processo."},
],
"Química Ambiental":[
{"title":"Ciclo da água","explain":"Evaporação, condensação e precipitação integram o ciclo hidrológico e influenciam transporte de substâncias.","example":"Água de lagos evapora e depois pode retornar como chuva.","question":"Qual etapa forma nuvens?","options":["Combustão","Oxidação do ferro","Condensação"],"correct":2,"feedback":"Resposta comentada: Água de lagos evapora e depois pode retornar como chuva. Evaporação, condensação e precipitação integram o ciclo hidrológico e influenciam transporte de substâncias."},
{"title":"Tratamento de água","explain":"Tratamento convencional pode envolver coagulação, floculação, decantação, filtração e desinfecção.","example":"Partículas suspensas podem ser removidas por floculação seguida de decantação.","question":"Qual etapa reduz microrganismos?","options":["Desinfecção","Aeração sempre","Aquecimento solar obrigatório"],"correct":0,"feedback":"Resposta comentada: Partículas suspensas podem ser removidas por floculação seguida de decantação. Tratamento convencional pode envolver coagulação, floculação, decantação, filtração e desinfecção."},
{"title":"Tratamento de esgoto","explain":"Processos físicos, químicos e biológicos removem sólidos e poluentes antes do lançamento ou reúso.","example":"Lodos ativados usam microrganismos para degradar matéria orgânica.","question":"Lodos ativados dependem de:","options":["Apenas luz","Microrganismos","Somente destilação"],"correct":1,"feedback":"Resposta comentada: Lodos ativados usam microrganismos para degradar matéria orgânica. Processos físicos, químicos e biológicos removem sólidos e poluentes antes do lançamento ou reúso."},
{"title":"Poluição atmosférica","explain":"Poluentes atmosféricos incluem material particulado, NOₓ, SO₂ e ozônio troposférico, com diferentes fontes e efeitos.","example":"Veículos e processos industriais podem emitir óxidos de nitrogênio.","question":"Qual é poluente atmosférico?","options":["Água pura sempre","Nitrogênio do ar em si","SO₂"],"correct":2,"feedback":"Resposta comentada: Veículos e processos industriais podem emitir óxidos de nitrogênio. Poluentes atmosféricos incluem material particulado, NOₓ, SO₂ e ozônio troposférico, com diferentes fontes e efeitos."},
{"title":"Chuva ácida","explain":"SO₂ e NOₓ podem formar ácidos na atmosfera, contribuindo para precipitação com pH reduzido.","example":"Emissões industriais podem contribuir para chuva ácida.","question":"Qual gás pode contribuir?","options":["SO₂","Hélio","Neônio"],"correct":0,"feedback":"Resposta comentada: Emissões industriais podem contribuir para chuva ácida. SO₂ e NOₓ podem formar ácidos na atmosfera, contribuindo para precipitação com pH reduzido."},
{"title":"Efeito estufa","explain":"Gases como CO₂, CH₄ e vapor d'água absorvem e emitem radiação infravermelha, influenciando o balanço energético da Terra.","example":"Aumento de CO₂ por atividades humanas intensifica o efeito estufa.","question":"Qual gás é relevante?","options":["Argônio apenas","CO₂","Hélio"],"correct":1,"feedback":"Resposta comentada: Aumento de CO₂ por atividades humanas intensifica o efeito estufa. Gases como CO₂, CH₄ e vapor d'água absorvem e emitem radiação infravermelha, influenciando o balanço energético da Terra."},
{"title":"Aquecimento global","explain":"Aumento de gases de efeito estufa por atividades humanas é principal causa do aquecimento global observado recentemente.","example":"Queima de combustíveis fósseis eleva emissões de CO₂.","question":"Qual atividade aumenta CO₂?","options":["Fotossíntese líquida","Reciclagem de vidro","Queima de combustíveis fósseis"],"correct":2,"feedback":"Resposta comentada: Queima de combustíveis fósseis eleva emissões de CO₂. Aumento de gases de efeito estufa por atividades humanas é principal causa do aquecimento global observado recentemente."},
{"title":"Eutrofização","explain":"Excesso de nutrientes como nitrogênio e fósforo pode estimular florações algais e reduzir oxigênio dissolvido.","example":"Fertilizantes carregados para lagos podem causar eutrofização.","question":"Qual fator favorece o processo?","options":["Excesso de nutrientes","Ausência total de água","Baixa concentração de nutrientes"],"correct":0,"feedback":"Resposta comentada: Fertilizantes carregados para lagos podem causar eutrofização. Excesso de nutrientes como nitrogênio e fósforo pode estimular florações algais e reduzir oxigênio dissolvido."},
{"title":"Resíduos e logística reversa","explain":"Logística reversa organiza retorno de produtos pós-consumo para tratamento, reaproveitamento ou destinação adequada.","example":"Pilhas usadas devem seguir pontos de coleta apropriados.","question":"Qual é exemplo de logística reversa?","options":["Jogar pilhas no lixo comum","Devolver pilhas a ponto de coleta","Queimar pilhas em casa"],"correct":1,"feedback":"Resposta comentada: Pilhas usadas devem seguir pontos de coleta apropriados. Logística reversa organiza retorno de produtos pós-consumo para tratamento, reaproveitamento ou destinação adequada."},
{"title":"Química verde","explain":"Química verde busca prevenir resíduos, reduzir toxicidade e usar recursos e energia de forma mais eficiente desde o projeto.","example":"Escolher solvente menos perigoso pode reduzir riscos e resíduos.","question":"Qual princípio combina com química verde?","options":["Gerar mais resíduos","Aumentar toxicidade","Prevenir geração de resíduos"],"correct":2,"feedback":"Resposta comentada: Escolher solvente menos perigoso pode reduzir riscos e resíduos. Química verde busca prevenir resíduos, reduzir toxicidade e usar recursos e energia de forma mais eficiente desde o projeto."},
],
};
export function getChemistryTopicLessons(topic:string):Lesson[]|undefined{return lessons[topic];}
